/* Original created/carded item commands, preflighted against per-copy ownership. */
#ifndef MYRO_NPC_ITEM_DETAIL64_H
#define MYRO_NPC_ITEM_DETAIL64_H
#include "npc_iteminfo_data64.h"
static int npc_item_detail_matches64(const OwnedItem52*p,uint32_t source,unsigned identified,unsigned refine,unsigned broken,const uint32_t*cards){return p->sourceID==source&&p->identified==identified&&p->refine==refine&&!!(p->flags&OWNED_BROKEN52)==broken&&!memcmp(p->cards,cards,4*sizeof(*cards));}
static int npc_item_detail_command64(NpcPlayer55*p,NpcMachine55*m,const char*name,const NpcValue55*args,unsigned count,NpcValue55*out){Combat*g=p->game;*out=npc_vm_number55(0);int give=!strcmp(name,"getitem2"),take=!strcmp(name,"delitem2"),query=!strcmp(name,"countitem2");
 if(give||take||query){if(count!=(query?8u:9u)&&!((give||take)&&count==10))return N55_ERROR;uint32_t source;int identified;int64_t amount=0,target;if(!npc_item_source55(m,args[0],give,&source,&identified))return N55_ERROR;if(count==10){if(!npc_vm_integer55(m,args[9],&target)||target<0||target>UINT32_MAX)return N55_ERROR;if((uint32_t)target!=p->accountId)return N55_READY;}unsigned offset=query?1:2;if(!query&&(!npc_vm_integer55(m,args[1],&amount)||amount<0||amount>INT_MAX))return N55_ERROR;int64_t values[7];for(unsigned i=0;i<7;i++)if(!npc_vm_integer55(m,args[offset+i],values+i)||values[i]<0||values[i]>(i==0||i==2?1:i==1?20:UINT32_MAX))return N55_ERROR;uint32_t cards[4];for(unsigned i=0;i<4;i++)cards[i]=(uint32_t)values[i+3];unsigned id=identified?(unsigned)values[0]:0,refine=(unsigned)values[1],broken=(unsigned)values[2];uint64_t available=0;for(unsigned i=0;i<g->owned52.count[0];i++)if(npc_item_detail_matches64(g->owned52.items+i,source,id,refine,broken,cards))available+=g->owned52.items[i].quantity;if(query){*out=npc_vm_number55((int64_t)available);return N55_READY;}if(!amount)return N55_READY;if(take&&(uint64_t)amount>available)return N55_ERROR;
 OwnedItems52*trial=malloc(sizeof(*trial));if(!trial)return N55_ERROR;*trial=g->owned52;inventory_compact52(trial);int ok=1;
 if(take){uint32_t left=(uint32_t)amount;for(unsigned i=0;i<trial->count[0]&&left;){OwnedItem52*item=trial->items+i;if(!npc_item_detail_matches64(item,source,id,refine,broken,cards)){i++;continue;}uint32_t uid=item->uid,n=item->quantity<left?item->quantity:left;int erased=n==item->quantity;if(item->equipped)owned_unequip52(trial,uid);if(owned_remove52(trial,0,uid,n)!=OWNED_OK52){ok=0;break;}left-=n;if(!erased)i++;}if(left)ok=0;}
 else{const OwnedRule52*r=item_rule52(source);uint32_t left=(uint32_t)amount;if(!owned_gear52(r))for(unsigned i=0;i<trial->count[0]&&left;i++){OwnedItem52*item=trial->items+i;if(item->equipped||item->bound||!npc_item_detail_matches64(item,source,id,refine,broken,cards)||item->quantity>=r->stackLimit)continue;uint32_t n=r->stackLimit-item->quantity;if(n>left)n=left;item->quantity+=n;left-=n;}while(left&&ok){if(trial->count[0]>=OWNED_BAG52||!trial->nextUID||trial->nextUID==UINT32_MAX){ok=0;break;}OwnedItem52*item=trial->items+trial->count[0]++;memset(item,0,sizeof(*item));item->uid=trial->nextUID++;item->sourceID=source;item->identified=(uint8_t)id;item->refine=(uint8_t)refine;item->flags=broken?OWNED_BROKEN52:0;memcpy(item->cards,cards,sizeof(cards));if(cards[0]>=254&&cards[0]<=256)item->flags|=OWNED_RESERVED_CARDS52;item->quantity=owned_gear52(r)?1:left>r->stackLimit?r->stackLimit:left;left-=item->quantity;}}
 if(ok&&!owned_valid52(trial,item_rule52))ok=0;if(ok&&give){int64_t weight=0;for(unsigned i=0;i<trial->count[0];i++)weight+=(int64_t)item_rule52(trial->items[i].sourceID)->weight*trial->items[i].quantity;if(weight>inventory_weight_max(g))ok=0;}if(ok){g->owned52=*trial;inventory_sync_gear52(g);stat_refresh(g);}free(trial);return ok?N55_READY:N55_ERROR;
 }
 if(!strcmp(name,"getiteminfo")){int64_t type;if(count!=2||!npc_vm_integer55(m,args[1],&type))return N55_ERROR;uint32_t source;int identified;if(!npc_item_source55(m,args[0],0,&source,&identified)){*out=npc_vm_number55(-1);return N55_READY;}const NpcItemInfo64*d=npc_item_info64(source);const OwnedRule52*r=item_rule52(source);const EquipmentRule52*e=equipment_rule52(source);int item=inventory_catalog52(source);if(!d||!r||item<0){*out=npc_vm_number55(-1);return N55_READY;}int64_t value;switch(type){case 0:value=d->buy;break;case 1:value=d->sell;break;case 2:value=d->type;break;case 4:value=e?e->sex:2;break;case 5:value=r->location;break;case 6:value=r->weight;break;case 7:value=itemDefs[item].attack;break;case 8:value=itemDefs[item].defense;break;case 9:value=e?e->range:0;break;case 10:value=r->slots;break;case 11:value=d->subtype;break;case 12:value=e?e->minLevel:0;break;case 13:value=e?e->weaponLevel:0;break;case 14:value=d->view;break;case 15:value=itemDefs[item].matk;break;case 16:value=d->sprite;break;case 17:value=d->trade;break;case 18:value=e?e->maxLevel:0;break;case 25:value=!r->refineable;break;case 42:value=source;break;case 44:*out=npc_vm_string55(itemDefs[item].name);return N55_READY;default:return N55_ERROR;}*out=npc_vm_number55(value);return N55_READY;}
 return-1;
}
#endif
